## Code Example
```javascript
// Pseudo-code: enqueue/dequeue
typedef struct { uint64_t gen; uint16_t pri; void *ptr; } slot_t;
typedef struct { slot_t *slots; _Atomic uint32_t head, tail; } ring_t;

// Enqueue pseudocode
void enqueue(ring_t *r, void *p, uint16_t pri) {
  uint32_t idx = atomic_fetch_add_explicit(&r->head, 1, memory_order_relaxed);
  slot_t *s = &r->slots[idx & (N-1)];
  s->ptr = p;
  s->pri = pri;
  atomic_thread_fence(memory_order_release);
  // publish idx
}
```

